import{esc,button,input,select}from'../phase4/ui.js';
import{labels,expected,countIf,rangeFor,clock}from'./b19-model.js';
const btn=(a,s,d='')=>button('b19-'+a,s,d),on=b=>`aria-pressed="${!!b}"`,f=(k,l,v)=>input(k,l,v,'autocomplete="off" spellcheck="false"'),sel=select;
const note=s=>`<p class="b19-note">${s}</p>`;
const prose=(k,l,v)=>`<details class="b19-optional"><summary>${l}</summary><label class="field b19-prose">${l}<textarea data-xfield="${k}" maxlength="800" rows="2">${esc(v)}</textarea><small>会保存你的说法，含义留给你继续说明。</small></label></details>`;
const steps=['定问题','记下来','算成表','画出来','回答'];
const table=(head,rs)=>`<table class="b19-table"><thead><tr>${head.map(s=>`<th>${esc(s)}</th>`).join('')}</tr></thead><tbody>${rs.map(r=>`<tr>${r.map(s=>`<td>${esc(s??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
function chart(ls,cs,unit,kind='bar',title='我的记录',numeric=false){const max=Math.max(4,...cs),h=150,scale=h/max;
 if(kind==='table')return`<div class="b19-plot"><h3>${esc(title)}</h3>${table(['类别',unit],ls.map((l,i)=>[l,cs[i]]))}</div>`;
 return`<div class="b19-plot"><h3>${esc(title)}</h3><p class="b19-axis">${esc(unit)} · 共同从0开始${kind==='dot'?' · 每点1'+esc(unit):''}</p><div class="b19-chart" style="--cols:${ls.length};--height:${h}px"><div class="b19-ticks">${[max,Math.floor(max/2),0].map(n=>`<span style="bottom:${n*scale}px">${n}</span>`).join('')}</div>${ls.map((l,i)=>`<div class="b19-column"><div class="b19-bar-area">${kind==='dot'?`<div class="b19-dots">${Array.from({length:cs[i]},(_,j)=>`<i style="bottom:${(j+1)*scale-6}px"></i>`).join('')}</div>`:`<div class="b19-bar" style="height:${cs[i]*scale}px"></div>`}<b>${cs[i]}</b></div><span>${esc(l)}${numeric?'小时':''}</span></div>`).join('')}</div></div>`;
}
const build=(ls,cs)=>`<div class="b19-adjust">${ls.map((l,i)=>`<div><span>${esc(l)} <b>${cs[i]}</b></span>${btn('bar','−',`data-index="${i}" data-delta="-1" aria-label="${esc(l)}减少1"`)}${btn('bar','＋',`data-index="${i}" data-delta="1" aria-label="${esc(l)}增加1"`)}</div>`).join('')}</div>`;
const pickExtremes=(ls,b)=>`<div class="b19-picks">${[['max','最多的，全部选出'],['min','最少的，全部选出']].map(([a,l])=>`<fieldset><legend>${l}</legend>${ls.map((s,i)=>btn(a,esc(s),`data-index="${i}" ${on(b[a].includes(i))}`)).join('')}</fieldset>`).join('')}</div>`;
const formulas=(t,m,ls,range)=>note(`在完整记录范围 <b>${range}</b> 中计数。写法如 =COUNTIF(${range},"${esc(ls[0])}")；把条件换成需要的类别。`)+`<div class="b19-fields">${ls.map((l,i)=>f('formulas.'+i,`数“${l}”的公式`,m.formulas[i])).join('')}</div>`;
function rawStudio(t,m){return`<details class="b19-raw"><summary>回看原卡片与已记表格</summary>${table(['行','编号',...t.cols.map((c,i)=>String.fromCharCode(66+i)+' · '+c.label),'原卡片'],t.rows.map((r,i)=>[i+2,r.id,...(m.board.rows[i]||t.cols.map(()=>null)),r.day+'：'+r.values.join(' / ')]))}</details>`;}
function studioVisual(t,m){const b=m.board,ls=labels(t);let body='';
 if(b.stage===0)body=`<div class="b19-card"><small>这次想知道</small><h3>${esc(t.title)}</h3><p>${esc(t.who)}</p><p>${esc(t.when)} · ${esc(t.how)}</p><p>${t.rows.length}份模拟记录${t.cols.length>1?`，每份回答${t.cols.length}题`:''}</p></div>`;
 if(b.stage===1){const r=t.rows[b.cursor];body=`<div class="b19-card"><small>原卡片 ${esc(r.id)} · ${esc(r.day)}</small>${t.cols.map((c,i)=>`<p>${esc(c.label)}：<strong>${esc(r.values[i])}${t.numeric&&i===t.analysis?'小时':''}</strong></p>`).join('')}<p>已记 ${b.rows.filter(Boolean).length}/${t.rows.length} 条</p></div>`;}
 if(b.stage===2){const cs=t.formula?ls.map((l,i)=>countIf(m.formulas[i],b.rows,t.analysis)?.value??'—'):m.counts;body=table(['类别',t.formula?'公式算出的次数':'我数出的次数'],ls.map((l,i)=>[l,cs[i]]));}
 if(b.stage>=3)body=chart(ls,b.heights,t.unit,b.stage===4?b.plot.chart:m.chart||'bar',t.title,t.numeric);
 return`<div class="b19-step">${steps.map((s,i)=>`<span ${i===b.stage?'aria-current="step"':''}>${i+1} ${s}</span>`).join('')}</div>${body}${b.stage>0?rawStudio(t,m):''}${b.report?`<div class="b19-card"><p>这组模拟记录中，${b.report.max.map(i=>esc(ls[i])+(t.numeric?'小时':'')).join('、')}出现最多：${b.table.counts[b.report.max[0]]}${esc(t.unit)}。</p><p>${b.report.min.map(i=>esc(ls[i])+(t.numeric?'小时':'')).join('、')}出现最少；最多与最少相差${b.report.gap}${esc(t.unit)}。</p><small>发现已保存，适用范围仍是这组记录。</small></div>`:''}`;
}
export function visual(t,m){const b=m.board;let v='';
 if(t.type==='x-datacount'){const cs=t.formula?t.labels.map((l,i)=>countIf(m.formulas[i],t.raw.map(v=>[v]),0)?.value||0):b.counts;v=table(['原记录的类别','次数'],t.labels.map((l,i)=>[l,t.counts[i]]))+chart(t.labels,cs,t.unit);if(t.raw)v+=`<details><summary>逐行原记录</summary>${table(['行','B · 类别'],t.raw.map((x,i)=>[i+2,x]))}</details>`;if(t.pair)v+=`<div class="b19-match">${t.compare.map(k=>`<div><strong>${esc(t.labels[k])}</strong>${Array.from({length:t.counts[k]},(_,i)=>`<i class="${i<b.pairs?'matched':''}">${i<b.pairs?'✓':'●'}</i>`).join('')}</div>`).join('')}</div>`;}
 if(t.type==='x-datastudio')v=studioVisual(t,m);
 if(t.type==='x-dataplan'||t.mode==='context')v=`<div class="b19-card"><small>${t.mode==='context'?'留下测量的来历':'让问题可以被回答'}</small>${t.choices.map((c,i)=>`<p>${esc(c.label)}：<strong>${esc(c.options.find(([v])=>v===m.answers[i])?.[1]||'还没选')}</strong></p>`).join('')}</div>`;
 if(t.type==='x-dataclean'){const r=t.rows[b.cursor];v=`<div class="b19-card"><small>原记录 ${r.id}</small><h3>${r.raw?esc(r.raw):'空白，没有回答'}</h3><p>${r.proof?'可核对的原答卷：'+esc(r.proof):t.labels.includes(r.raw)?'这是允许的颜色选项。':'没有其他可核对的凭据。'}</p></div>`+table(['记录','原值','我的处理','用于计数'],t.rows.map((r,i)=>[r.id,r.raw||'空白',b.decisions[i]?({keep:'保留',correct:'按凭据更正',unknown:'标为未知',exclude:'暂不计入'})[b.decisions[i].decision]:'待处理',b.decisions[i]?.value||'—']));}
 if(t.type==='x-datakind')v=`<div class="b19-kind">${t.cards.map((c,i)=>`<article><p>${esc(c.label)}</p><b>${b.placed[i]==='nominal'?'名称，没有固定高低':b.placed[i]==='ordinal'?'等级，有固定高低':'还没分组'}</b></article>`).join('')}</div>`;
 if(t.type==='x-measurestory'&&t.mode==='round'){v=`<div class="b19-card"><small>模拟时刻 · 取到最近半小时；恰好一半记到后一个</small><h3>${b.cursor<t.times.length?clock(t.times[b.cursor]):'都记完了'}</h3><p>已处理 ${b.cursor}/${t.times.length} 条</p></div>`;if(b.rounded.length)v+=table(['原时刻','取整后的时刻'],b.rounded.map((n,i)=>[clock(t.times[i]),clock(n)]))+chart(['21:00','21:30'],[b.rounded.filter(n=>n===1260).length,b.rounded.filter(n=>n===1290).length],'条报告','bar','取整后是否聚在一起？');}
 return`<div class="b19-world">${note('模拟数据 · 可以观察规律，不能当作真实调查结果')}${v}</div>`;
}
export function controls(t,m){const b=m.board;let v='';
 if(t.type==='x-datacount'){v=t.formula?formulas(t,m,t.labels,`B2:B${t.raw.length+1}`):build(t.labels,b.counts);if(t.pair)v+=btn('pair','配成一对',b.pairs>=Math.min(...t.compare.map(k=>t.counts[k]))?'disabled':'');v+=`<div class="b19-fields">${f('total','总共多少'+t.unit,m.total)}${f('gap',`${t.labels[t.compare[0]]}与${t.labels[t.compare[1]]}相差多少`,m.gap)}${t.unknown?f('unknown','另外还有几条未知',m.unknown):''}${t.scope?sel('scope','这里数的是什么？',m.scope,[['visits','使用次数；同一人可能出现多次'],['people','一定是不同人数']]):''}</div>`;if(t.extremes)v+=pickExtremes(t.labels,b);}
 if(t.type==='x-dataplan'||t.mode==='context')v=`<div class="b19-fields">${t.choices.map((c,i)=>sel('answers.'+i,c.label,m.answers[i],c.options)).join('')}</div>${t.draft||t.mode==='context'?prose('draft','也可以用自己的话留下计划或背景（可选）',m.draft):''}${btn('plan','把这些放在一起检查')}`;
 if(t.type==='x-datastudio'){
  const ls=labels(t);
  if(b.stage===0)v=`<div class="b19-fields">${t.cols.map((c,i)=>sel('questions.'+i,'问题'+(i+1),m.questions[i],[['clear',c.question],['vague','平时怎么样？'],['lead','你一定和大多数人一样吧？']])).join('')}${sel('scope','问谁、什么时候',m.scope,[['defined',t.who+' · '+t.when],['any','对象和时间随便变']])}${sel('reason','怎样保持可比较',m.reason,[['consistent',t.how+'；用同一问法和单位'],['guess','按印象猜每个人的答案']])}</div>${prose('draft','自己的问法（可选）',m.draft)}${btn('plan','问题定好了，开始记')}`;
  if(b.stage===1)v=`<div class="b19-fields">${t.cols.map((c,i)=>sel('entry.'+i,'记下这条的'+c.label,m.entry[i],c.values)).join('')}</div>${btn('record','保存这条记录')}`;
  if(b.stage===2)v=(t.formula?formulas(t,m,ls,rangeFor(t)):`<div class="b19-fields">${ls.map((l,i)=>f('counts.'+i,`${l}的次数`,m.counts[i])).join('')}</div>`)+f('total','总共多少条记录',m.total)+btn('table','核对原记录与表格');
  if(b.stage===3)v=`<div class="b19-fields">${sel('chart','怎么表示',m.chart,t.charts.map(c=>[c,({bar:'柱形图',dot:'点图',table:'表格'})[c]]))}${sel('title','标题',m.title,[['question',t.title],['wrong','所有孩子都这样']])}${sel('xaxis','分类这一边表示',m.xaxis,[['variable',t.cols[t.analysis].label],['wrong','记录编号']])}${sel('yaxis','数量这一边表示',m.yaxis,[['frequency',t.unit],['wrong','喜欢的程度']])}${sel('reason','选它的理由',m.reason,[['compare','柱形高度方便比较次数'],['distribution','点的分布显示数量怎样分散'],['exact','表格方便查准确次数']])}</div>${build(ls,b.heights)}${btn('plot','图与表对上了')}`;
  if(b.stage===4)v=pickExtremes(ls,b)+`<div class="b19-fields">${f('gap','最多与最少相差多少'+t.unit,m.gap)}${sel('scope','我能说到哪里',m.scope,[['records','只说这组模拟记录'],['all','所有孩子都如此']])}${sel('limit','还有什么限制',m.limit,[['sample','这一组人未必代表其他人'],['time','别的时间可能不同'],['recall','回忆或估计可能有误差'],['none','有图就没有限制']])}${sel('improve','下次可以怎样改进',m.improve,[['repeat','同样方法再记录其他时段'],['wider','按计划纳入更多不同的人'],['precise','统一记录方式并核对原记录'],['erase','删掉不喜欢的答案']])}</div>${prose('finding1','第一条发现（用自己的话，可选）',m.finding1)}${prose('finding2','第二条发现（用自己的话，可选）',m.finding2)}${btn('report','留下这次发现')}`;
  if(b.stage>0&&b.rows.some(Boolean))v+=`<details class="b19-edit"><summary>更正记录或保存表格</summary>${sel('editIndex','回到哪条记录',m.editIndex,t.rows.flatMap((r,i)=>b.rows[i]?[[String(i),r.id+' · '+r.day]]:[]))}${btn('edit','回到这条，更正后重新统计')}${btn('export','下载当前记录 CSV')}<p>后面的表图会重新核对，旧尝试仍保留。</p></details>`;
 }
 if(t.type==='x-dataclean')v=`<div class="b19-row-nav">${t.rows.map((r,i)=>btn('row',r.id,`data-index="${i}" ${on(b.cursor===i)}`)).join('')}</div><div class="b19-fields">${sel('decision','这一条怎样处理',m.decision,[['keep','保留'],['correct','按凭据更正'],['unknown','标记未知'],['exclude','暂不计入统计']])}${sel('correction','如果更正，改成',m.correction,t.labels)}${sel('cleanReason','依据是什么',m.cleanReason,[['valid','原值是有效选项'],['proof','原答卷可以核对'],['no-proof','没有凭据，不能猜'],['majority','跟着多数人改']])}</div>${btn('clean','留下这一条的处理')}<div class="b19-fields">${f('usable','最后有几条可计入',m.usable)}${f('unknown','几条仍然未知',m.unknown)}</div>`;
 if(t.type==='x-datakind')v=t.cards.map((c,i)=>`<fieldset><legend>${esc(c.label)}</legend>${btn('kind','名称，无固定高低',`data-index="${i}" data-kind="nominal" ${on(b.placed[i]==='nominal')}`)}${btn('kind','等级，有固定高低',`data-index="${i}" data-kind="ordinal" ${on(b.placed[i]==='ordinal')}`)}</fieldset>`).join('')+`<div class="b19-fields">${sel('orderReason','两种分法的差别',m.orderReason,[['order','评分带有先后高低，颜色名称本身没有'],['number','只要写成数字就有高低']])}${sel('precisionReason','评分1到2与4到5',m.precisionReason,[['not-equal','只知道顺序，不一定是同样大的感受差'],['equal','一定相差一样多']])}</div>${btn('classify','检查我的分组')}`;
 if(t.type==='x-measurestory'&&t.mode==='round')v=!b.started?sel('guess','先留下猜想',m.guess,[['exact','可能所有人都在这些整点睡'],['rounding','可能是取整造成的'],['unknown','还不能判断']])+btn('start-round','用一组模拟时刻试试看'):b.cursor<t.times.length?f('roundAnswer','最近半小时是几点？例如21:00',m.roundAnswer)+btn('round','留下这个取整结果'):sel('conclusion','这次实验说明什么',m.conclusion,[['possible','取整可能造成堆积；不能据此确定真实原因'],['proof','证明所有真实回答都经过取整'],['same','证明每个人原本时刻一样']]);
 return`<div class="b19-controls">${v}${m.issue?`<p class="b19-issue" role="status">${esc(m.issue)}</p>`:''}</div>`;
}
export const render=(t,m)=>`<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div>`;
export function csv(t,m){const cell=x=>'"'+String(x??'').replaceAll('"','""')+'"';return'\uFEFF'+[['模拟记录编号',...t.cols.map(c=>c.label)],...t.rows.flatMap((r,i)=>m.board.rows[i]?[[r.id,...m.board.rows[i]]]:[])].map(r=>r.map(cell).join(',')).join('\r\n');}
